import XCTest
import Foundation
import Synchronization
import AgentRuntimeKit
import AgentSessionSidebar

private func id(_ n:Int)->UUID {UUID(uuidString:String(format:"00000000-0000-0000-0000-%012d",n))!}
private struct Record:Sendable {let id:UUID;let tab:UUID?;var date:Date?;var saved:Date;var name:String;var admitted:Bool=true}
private func sidebarRecord(_ n:Int,tab:Int?=1,date:Double?=nil,saved:Double=100)->Record {.init(id:id(n),tab:tab.map(id),date:date.map{Date(timeIntervalSince1970:$0)},saved:Date(timeIntervalSince1970:saved),name:"stored-\(n)")}
private struct ProbeState {var loads=0;var fast=0;var single:[UUID]=[];var events:[(String,[String:String])]=[];var started=false;var cancelled=false}
private final class Probe:Sendable {let state=Mutex(ProbeState())}
private func ports(_ records:[Record],fast:Bool=true,probe:Probe=Probe())->AgentSessionSidebarServices<Record> {
    .init(loadRecords:{probe.state.withLock{$0.loads+=1};return records},fastRecords:{probe.state.withLock{$0.fast+=1};return fast ? .init(records:records,source:"cached"):nil},loadRecord:{id in probe.state.withLock{$0.single.append(id)};return records.first{$0.id==id}},sortedRecords:{$0.sorted{$0.saved > $1.saved}},sessionID:{$0.id},tabID:{$0.tab},name:{$0.name},entry:{r,tab,name in guard r.admitted else{return nil};return .init(id:r.id,tabID:tab,name:name,lastUserMessageAt:r.date,savedAt:r.saved,itemCount:1,autoEditEnabled:false,hasUnknownConversationContent:false,isMCPOriginated:false)},observe:{name,fields in probe.state.withLock{$0.events.append((name,fields))}})
}
@MainActor
final class SidebarTests:XCTestCase {
    func query(_ tabs:[Int]=[1],bound:[Int:Int]=[:],prioritized:Int?=nil,names:[Int:String]=[:])->AgentSessionSidebarQuery {
        .init(tabNameByID:Dictionary(uniqueKeysWithValues:names.map{(id($0.key),$0.value)}),validTabIDs:Set(tabs.map(id)),boundSessionIDByTabID:Dictionary(uniqueKeysWithValues:bound.map{(id($0.key),id($0.value))}),prioritizedTabID:prioritized.map(id))
    }
    private func batches(_ s:AgentSessionSidebarService<Record>,_ q:AgentSessionSidebarQuery,size:Int=8) async throws->[AgentSessionSidebarBuildBatch] {var result:[AgentSessionSidebarBuildBatch]=[];for try await b in s.buildSidebarIndexStream(q,batchSize:size){result.append(b)};return result}
    func testEmptyIndexProducesNoBatches() async throws {let b=try await batches(.init(services:ports([])),query());XCTAssertTrue(b.isEmpty)}
    func testExplicitBindingWinsOverNewerSessionForSameTab() async throws {let s=AgentSessionSidebarService(services:ports([sidebarRecord(10,saved:1),sidebarRecord(11,saved:100)])),r=try await s.buildSidebarIndex(query(bound:[1:10]));XCTAssertEqual(r.preferredSessionIDByTabID[id(1)],id(10));XCTAssertEqual(r.entriesBySessionID.count,2)}
    func testExplicitBindingReassignsStaleComposeTabWithoutLeakingIt() async throws {let s=AgentSessionSidebarService(services:ports([sidebarRecord(10,tab:2)])),r=try await s.buildSidebarIndex(query([1,2],bound:[1:10]));XCTAssertEqual(r.preferredSessionIDByTabID,[id(1):id(10)]);XCTAssertEqual(r.entriesBySessionID[id(10)]?.tabID,id(1))}
    func testInvalidBoundTabIsIgnored() async throws {let r=try await AgentSessionSidebarService(services:ports([sidebarRecord(10,tab:2)])).buildSidebarIndex(query([2],bound:[1:10]));XCTAssertEqual(r.preferredSessionIDByTabID,[id(2):id(10)])}
    func testMissingExplicitBindingAllowsRecordedTabFallbackInFullProjection() async throws {let r=try await AgentSessionSidebarService(services:ports([sidebarRecord(10)])).buildSidebarIndex(query(bound:[1:99]));XCTAssertEqual(r.preferredSessionIDByTabID[id(1)],id(10))}
    func testDuplicateRecordIdentityUsesFirstSortedRecord() async throws {let a=sidebarRecord(10,saved:1),b=sidebarRecord(10,saved:200);let r=try await AgentSessionSidebarService(services:ports([a,b])).buildSidebarIndex(query(bound:[1:10]));XCTAssertEqual(r.entriesBySessionID[id(10)]?.savedAt,b.saved)}
    func testHostNamesOverrideRecordNamesAndUnknownTabsAreIgnored() async throws {let r=try await AgentSessionSidebarService(services:ports([sidebarRecord(10),sidebarRecord(11,tab:9),sidebarRecord(12,tab:nil)])).buildSidebarIndex(query(names:[1:"display"]));XCTAssertEqual(r.entriesBySessionID.count,1);XCTAssertEqual(r.entriesBySessionID[id(10)]?.name,"display")}
    func testEntryAdmissionFailureSkipsRecord() async throws {var r=sidebarRecord(10);r.admitted=false;let result=try await AgentSessionSidebarService(services:ports([r])).buildSidebarIndex(query());XCTAssertTrue(result.entriesBySessionID.isEmpty)}
    func testPreferredUserRecencyBeatsNewerSavedOnlySession() async throws {let r=try await AgentSessionSidebarService(services:ports([sidebarRecord(10,date:1,saved:1),sidebarRecord(11,saved:1000)])).buildSidebarIndex(query());XCTAssertEqual(r.preferredSessionIDByTabID[id(1)],id(10))}
    func testPreferenceTieBreaksSavedDateThenRawIdentity() async throws {let r=try await AgentSessionSidebarService(services:ports([sidebarRecord(12,date:10,saved:100),sidebarRecord(11,date:10,saved:100),sidebarRecord(10,date:10,saved:1)])).buildSidebarIndex(query());XCTAssertEqual(r.preferredSessionIDByTabID[id(1)],id(11))}
    func testPrioritizedTabIsYieldedFirstThenPreferredBatchesThenRemainder() async throws {let s=AgentSessionSidebarService(services:ports([sidebarRecord(10,tab:1),sidebarRecord(11,tab:2),sidebarRecord(12,tab:3),sidebarRecord(13,tab:1,saved:1)])),b=try await batches(s,query([1,2,3],prioritized:2),size:1);XCTAssertEqual(b[0].preferredSessionIDByTabID,[id(2):id(11)]);XCTAssertEqual(b.count,4);XCTAssertEqual(b.last?.entriesBySessionID.keys.map{$0},[id(13)]);XCTAssertTrue(b.last!.preferredSessionIDByTabID.isEmpty)}
    func testBatchSizeZeroClampsToOneAndDoesNotDuplicatePriority() async throws {let b=try await batches(.init(services:ports([sidebarRecord(10,tab:1),sidebarRecord(11,tab:2)])),query([1,2],prioritized:1),size:0);XCTAssertEqual(b.count,2);XCTAssertEqual(b.flatMap{$0.entriesBySessionID.keys}.count,2)}
    func testPreferredOrderingUsesActivityThenSaveThenTabIdentity() async throws {let b=try await batches(.init(services:ports([sidebarRecord(10,tab:2,date:10,saved:100),sidebarRecord(11,tab:1,date:10,saved:100),sidebarRecord(12,tab:3,date:20,saved:1)])),query([1,2,3]),size:1);XCTAssertEqual(b.map{$0.preferredSessionIDByTabID.keys.first!},[id(3),id(1),id(2)])}
    func testNonpreferredEntriesUseOneFinalBatchRegardlessOfPreferredBatchSize() async throws {let b=try await batches(.init(services:ports((10...14).map{sidebarRecord($0,saved:Double($0))})),query(),size:1);XCTAssertEqual(b.count,2);XCTAssertEqual(b[0].entriesBySessionID.count,1);XCTAssertEqual(b[1].entriesBySessionID.count,4);XCTAssertTrue(b[1].preferredSessionIDByTabID.isEmpty)}
    func testAggregateMergesAllBatchesWithoutLosingPreferredBindings() async throws {let r=try await AgentSessionSidebarService(services:ports([sidebarRecord(10),sidebarRecord(11,saved:1)])).buildSidebarIndex(query());XCTAssertEqual(r.entriesBySessionID.count,2);XCTAssertEqual(r.preferredSessionIDByTabID,[id(1):id(10)])}
    func testPrioritizedFastIndexExplicitSessionReturnsOnlyBinding() async throws {let p=Probe();let r=try await AgentSessionSidebarService(services:ports([sidebarRecord(10),sidebarRecord(11,saved:1)],probe:p)).buildPrioritizedSidebarIndex(query(bound:[1:11]));XCTAssertEqual(r.entriesBySessionID.count,1);XCTAssertEqual(r.preferredSessionIDByTabID,[id(1):id(11)]);XCTAssertEqual(p.state.withLock{$0.loads},0);XCTAssertTrue(p.state.withLock{$0.single.isEmpty})}
    func testPrioritizedFastIndexMissingExplicitBindingDoesNotFallback() async throws {let r=try await AgentSessionSidebarService(services:ports([sidebarRecord(10)])).buildPrioritizedSidebarIndex(query(bound:[1:99]));XCTAssertTrue(r.entriesBySessionID.isEmpty)}
    func testPrioritizedFastIndexWithoutBindingChoosesPreferredOnly() async throws {let r=try await AgentSessionSidebarService(services:ports([sidebarRecord(10,saved:1),sidebarRecord(11,saved:100)])).buildPrioritizedSidebarIndex(query());XCTAssertEqual(r.entriesBySessionID.count,1);XCTAssertEqual(r.preferredSessionIDByTabID[id(1)],id(11))}
    func testTargetedMissingIndexWithoutBindingNeverLoadsFullIndex() async throws {let p=Probe();let r=try await AgentSessionSidebarService(services:ports([sidebarRecord(10)],fast:false,probe:p)).buildPrioritizedSidebarIndex(query());XCTAssertTrue(r.entriesBySessionID.isEmpty);XCTAssertEqual(p.state.withLock{$0.loads},0);XCTAssertTrue(p.state.withLock{$0.single.isEmpty})}
    func testTargetedMissingIndexLoadsOnlyExplicitSession() async throws {let p=Probe();let r=try await AgentSessionSidebarService(services:ports([sidebarRecord(10,tab:2)],fast:false,probe:p)).buildPrioritizedSidebarIndex(query(bound:[1:10]));XCTAssertEqual(r.preferredSessionIDByTabID,[id(1):id(10)]);XCTAssertEqual(p.state.withLock{$0.single},[id(10)]);XCTAssertEqual(p.state.withLock{$0.loads},0)}
    func testTargetedMissingExplicitFileReturnsEmpty() async throws {let r=try await AgentSessionSidebarService(services:ports([],fast:false)).buildPrioritizedSidebarIndex(query(bound:[1:10]));XCTAssertTrue(r.entriesBySessionID.isEmpty)}
    func testTargetedOrdinaryLoadErrorIsTreatedAsMissing() async throws {struct Failure:Error{};var p=ports([],fast:false);p.loadRecord={_ in throw Failure()};let r=try await AgentSessionSidebarService(services:p).buildPrioritizedSidebarIndex(query(bound:[1:10]));XCTAssertTrue(r.entriesBySessionID.isEmpty)}
    func testTargetedCancellationErrorIsNotSwallowed() async {var p=ports([],fast:false);p.loadRecord={_ in throw CancellationError()};do {_ = try await AgentSessionSidebarService(services:p).buildPrioritizedSidebarIndex(query(bound:[1:10]));XCTFail("cancelled")}catch{XCTAssertTrue(error is CancellationError)}}
    func testMultipleTabsUseFullBuildRatherThanFastTargetedPath() async throws {let p=Probe();let r=try await AgentSessionSidebarService(services:ports([sidebarRecord(10),sidebarRecord(11,tab:2)],probe:p)).buildPrioritizedSidebarIndex(query([1,2]));XCTAssertEqual(r.entriesBySessionID.count,2);XCTAssertEqual(p.state.withLock{$0.loads},1);XCTAssertEqual(p.state.withLock{$0.fast},0)}
    func testFastIndexErrorsPropagateRatherThanUsingSingleFileFallback() async {struct Failure:Error{};var p=ports([]);p.fastRecords={throw Failure()};do {_ = try await AgentSessionSidebarService(services:p).buildPrioritizedSidebarIndex(query(bound:[1:10]));XCTFail("error")}catch{XCTAssertTrue(error is Failure)}}
    func testStreamLoaderErrorsReachConsumer() async {struct Failure:Error{};var p=ports([]);p.loadRecords={throw Failure()};do {_ = try await batches(.init(services:p),query());XCTFail("error")}catch{XCTAssertTrue(error is Failure)}}
    func testConsumerCancellationCancelsSuspendedProducer() async throws {let probe=Probe();var p=ports([],probe:probe);p.loadRecords={probe.state.withLock{$0.started=true};do{try await Task.sleep(for:.seconds(30));return []}catch{probe.state.withLock{$0.cancelled=Task.isCancelled};throw error}};let service=AgentSessionSidebarService(services:p),q=query();let consumer=Task {for try await _ in service.buildSidebarIndexStream(q){}};for _ in 0..<100 {if probe.state.withLock({$0.started}){break};try await Task.sleep(for:.milliseconds(5))};XCTAssertTrue(probe.state.withLock{$0.started});consumer.cancel();_ = try? await consumer.value;for _ in 0..<100 {if probe.state.withLock({$0.cancelled}){break};try await Task.sleep(for:.milliseconds(5))};XCTAssertTrue(probe.state.withLock{$0.cancelled})}
    func testActorIsolationIsInheritedByStreamProjection() async throws {actor Owner {func run() async throws {let owner=self;var p=ports([sidebarRecord(10)]);let base=p.entry;p.entry={r,tab,name in owner.preconditionIsolated();return base(r,tab,name)};_ = try await AgentSessionSidebarService(services:p).buildSidebarIndex(.init(tabNameByID:[:],validTabIDs:[id(1)]))}};try await Owner().run()}
    func testDiagnosticsReportPriorityAndTargetedScanSource() async throws {let p=Probe(),s=AgentSessionSidebarService(services:ports([sidebarRecord(10),sidebarRecord(11)],probe:p));_ = try await batches(s,query(prioritized:1));XCTAssertTrue(p.state.withLock{$0.events.contains{$0.0=="agentSessionIndex.streamYieldComplete" && $0.1["prioritizedYielded"]=="true"}});_ = try await s.buildPrioritizedSidebarIndex(query(bound:[1:11]));XCTAssertTrue(p.state.withLock{$0.events.contains{$0.0=="agentSessionIndex.prioritizedTargetedBuilt" && $0.1["source"]=="cached" && $0.1["recordsScanned"]=="2"}})}
    func testOrderingFallbackActivityAndRawIdentityArePreserved() {let a=AgentSessionIndexEntry(id:id(10),tabID:id(1),name:"a",savedAt:Date(timeIntervalSince1970:100),itemCount:0,autoEditEnabled:false,hasUnknownConversationContent:false,isMCPOriginated:false),b=AgentSessionIndexEntry(id:id(11),tabID:id(1),name:"b",savedAt:a.savedAt,itemCount:0,autoEditEnabled:false,hasUnknownConversationContent:false,isMCPOriginated:false);XCTAssertTrue(AgentSessionSidebarOrdering.shouldPreferSidebarEntry(a,over:b));XCTAssertEqual(AgentSessionSidebarOrdering.sidebarActivityDate(for:a),a.savedAt)}
    func testPrioritizedDuplicateExplicitRecordAdmissionFailureStopsAtFirstMatch() async throws {
        var bad=sidebarRecord(10,saved:1);bad.admitted=false;let good=sidebarRecord(10,saved:100)
        let r=try await AgentSessionSidebarService(services:ports([bad,good])).buildPrioritizedSidebarIndex(query(bound:[1:10]));XCTAssertTrue(r.entriesBySessionID.isEmpty)
    }
    func testEmptyTabSetUsesFullLoadButReturnsNoEntries() async throws {
        let p=Probe();let r=try await AgentSessionSidebarService(services:ports([sidebarRecord(10)],probe:p)).buildPrioritizedSidebarIndex(query([]));XCTAssertTrue(r.entriesBySessionID.isEmpty);XCTAssertEqual(p.state.withLock{$0.loads},1)
    }
    func testNegativeBatchSizeUsesOneAndUnrecognizedPriorityDoesNotAddBatch() async throws {
        let b=try await batches(.init(services:ports([sidebarRecord(10,tab:1),sidebarRecord(11,tab:2)])),query([1,2],prioritized:99),size:-8);XCTAssertEqual(b.count,2);XCTAssertTrue(b.allSatisfy{$0.entriesBySessionID.count==1})
    }
    func testPreferredRecencyUsesUserDateBeforeSaveDateEvenWhenOlder() async throws {
        let r=try await AgentSessionSidebarService(services:ports([sidebarRecord(10,date:1,saved:999),sidebarRecord(11,date:2,saved:1)])).buildSidebarIndex(query());XCTAssertEqual(r.preferredSessionIDByTabID[id(1)],id(11))
    }
    func testExplicitBindingToRecordWithNoOriginalTabIsAdmitted() async throws {
        let r=try await AgentSessionSidebarService(services:ports([sidebarRecord(10,tab:nil)])).buildSidebarIndex(query(bound:[1:10]));XCTAssertEqual(r.entriesBySessionID[id(10)]?.tabID,id(1))
    }
    func testFastRecordsSourceRemainsHostSuppliedInObservations() async throws {
        let probe=Probe();var p=ports([sidebarRecord(10)],probe:probe);p.fastRecords={.init(records:[sidebarRecord(10)],source:"host-specific")};_ = try await AgentSessionSidebarService(services:p).buildPrioritizedSidebarIndex(query())
        XCTAssertTrue(probe.state.withLock{$0.events.contains{$0.1["source"]=="host-specific"}})
    }

}
